                place[b].remove(j)
                place[a].append(j)
                place[b].append(i)
                rem[a] += sizes[i] - sizes[j]
                rem[b] += sizes[j] - sizes[i]
                weight[a] += values[j] - values[i]
                weight[b] += values[i] - values[j]
        return place, rem, weight

